package io.knowledgebrain.activity;
import java.net.*;import java.net.http.*;import java.nio.file.*;import java.security.*;import java.security.cert.CertificateFactory;import java.time.Duration;import javax.net.ssl.*;
import java.io.*;import java.nio.ByteBuffer;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.Flow;
final class ActivityHttp {
 static URI origin(String raw){var u=URI.create(raw);if(!"https".equals(u.getScheme())||u.getHost()==null||!u.getRawPath().isEmpty()||u.getRawQuery()!=null||u.getRawFragment()!=null||u.getRawUserInfo()!=null)throw new IllegalArgumentException("Fixed HTTPS origin required");return u;}
 static HttpClient client(String trust)throws Exception{var k=KeyStore.getInstance("PKCS12");k.load(null,null);try(var f=Files.newInputStream(Path.of(trust))){int i=0;for(var c:CertificateFactory.getInstance("X.509").generateCertificates(f))k.setCertificateEntry("ca-"+i++,c);}var t=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());t.init(k);var s=SSLContext.getInstance("TLS");s.init(null,t.getTrustManagers(),null);return HttpClient.newBuilder().sslContext(s).connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();}
 static HttpResponse<byte[]> send(HttpClient client,HttpRequest request,int max){try{return client.send(request,info->new Bounded(max));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Activity request interrupted");}catch(IOException e){throw new IllegalStateException("Activity dependency unavailable");}}
 static final class Bounded implements HttpResponse.BodySubscriber<byte[]>{private final int max;private final ByteArrayOutputStream bytes=new ByteArrayOutputStream();private final CompletableFuture<byte[]> result=new CompletableFuture<>();private Flow.Subscription sub;Bounded(int max){this.max=max;}public CompletionStage<byte[]> getBody(){return result;}public void onSubscribe(Flow.Subscription s){sub=s;s.request(1);}public void onNext(List<ByteBuffer> values){for(var v:values){if(v.remaining()>max-bytes.size()){sub.cancel();result.completeExceptionally(new IOException("Activity response too large"));return;}byte[] b=new byte[v.remaining()];v.get(b);bytes.writeBytes(b);}sub.request(1);}public void onError(Throwable e){result.completeExceptionally(e);}public void onComplete(){result.complete(bytes.toByteArray());}}
}
